def _key(units):
    return hashlib.sha1(struct.pack('<%dH' % len(units), *units)).hexdigest()[:16]


def _rebuild(units, segs):
    out = []
    for seg in segs:
        if isinstance(seg, tuple):
            a, b = seg
            if not (0 <= a <= b <= len(units)):
                return None
            out.extend(units[a:b])
        elif isinstance(seg, list):
            out.extend(seg)
        elif isinstance(seg, dict):
            # {'refill': [(a, b), ...]}: those slices of the units, joined, with
            # the scream they hold laid out again from the top of a row
            part = []
            for a, b in seg['refill']:
                if not (0 <= a <= b <= len(units)):
                    return None
                part.extend(units[a:b])
            out.extend(dstext.refill_units(part))
        else:
            raise TypeError('sentence_breaks: bad segment %r' % (seg,))
    return out


def apply(entry, string_index, units):
    """Return (new_units, status). status is None when this (entry, string) has
    no row (units passed through unchanged, not counted); True when the source
    hash matched and every listed break was moved; False when the source hash
    did not match or the rebuilt stream is not the expected one (a different
    build of this string): units are left untouched and the caller counts a
    fallback for each listed break."""
    row = SENTENCE_BREAKS.get((entry, string_index))
    if row is None:
        return units, None
    u = list(units)
    if _key(u) != row['hash']:
        return units, False
    new = _rebuild(u, row['segs'])
    if new is None or _key(new) != row['want']:
        return units, False
    return new, True


def patch_entry(entry_id, entry_bytes):
    """Apply every SENTENCE_BREAKS row of this entry. Returns (new_bytes, moved,
    fallback), both counted in box breaks, not strings. Every string's tail
    (spt.tails) is carried over unchanged, as in tools/skipguard.py."""
    rows = [si for (ei, si) in SENTENCE_BREAKS if ei == entry_id]
    if not rows or not entry_bytes or entry_bytes[:4] != b' TPS':
        return entry_bytes, 0, 0
    h = parse(entry_bytes, True)[0]
    keep = _spt_tails(entry_bytes, True)
    S = list(all_strings(entry_bytes, True))
    moved = fallback = 0
    seen = set()
    new = []
    for si, a, _ln, u in S:
        nu, status = apply(entry_id, si, u) if si in rows else (u, None)
        new.append((a, list(nu)))
        if status is not None:
            seen.add(si)
            n = len(SENTENCE_BREAKS[(entry_id, si)]['boxes'])
            if status:
                moved += n
            else:
                fallback += n
    for si in rows:
        if si not in seen:
            fallback += len(SENTENCE_BREAKS[(entry_id, si)]['boxes'])
    if not moved:
        return entry_bytes, 0, fallback
    return (build_ds(new[0][1], new[1:], h['term'], h['scale'], h['last'], tails=keep),
            moved, fallback)
